using OfficeOpenXml.Interfaces.Drawing.Text;

namespace EPPlus.Fonts.OpenType.Tests.Integration
{
    [TestClass]
    public class EnsureWrappingWithFreeFonts : FontTestBase
    {
        const double MaxWidthInPoints = 47.177401574803149606299212598425d;
        const string TestText = "Open sans";
        public override TestContext? TestContext { get; set; }

        [TestMethod]
        public void TestWrappingOpenSans()
        {
            var mf = new MeasurementFont()
            {
                FontFamily = "Open Sans",
                Size = 12f,
                Style = MeasurementFontStyles.Regular
            };

            var tle = OpenTypeFonts.GetTextLayoutEngineForFont(mf, FontFolders);

            var resultStrings = tle.WrapText(TestText, mf.Size, MaxWidthInPoints);
            Assert.AreEqual(2, resultStrings.Count);
            Assert.AreEqual("Open", resultStrings[0]);
            Assert.AreEqual("sans", resultStrings[1]);
        }

        [TestMethod]
        public void TestWrappingUnicaOne()
        {
            var mf = new MeasurementFont()
            {
                FontFamily = "Unica One",
                Size = 12f,
                Style = MeasurementFontStyles.Regular
            };

            var tle = OpenTypeFonts.GetTextLayoutEngineForFont(mf, FontFolders);

            var resultStrings = tle.WrapText(TestText, mf.Size, MaxWidthInPoints);
            Assert.AreEqual(2, resultStrings.Count);
            Assert.AreEqual("Open", resultStrings[0]);
            Assert.AreEqual("sans", resultStrings[1]);
        }

        [TestMethod]
        public void TestWrappingPinyon()
        {
            var mf = new MeasurementFont()
            {
                FontFamily = "Pinyon Script",
                Size = 12f,
                Style = MeasurementFontStyles.Regular
            };

            var tle = OpenTypeFonts.GetTextLayoutEngineForFont(mf, FontFolders);

            var resultStrings = tle.WrapText(TestText, mf.Size, MaxWidthInPoints);
            Assert.AreEqual(1, resultStrings.Count);
            Assert.AreEqual("Open sans", resultStrings[0]);
        }

        [TestMethod]
        public void TestWrappingOi()
        {
            var mf = new MeasurementFont()
            {
                FontFamily = "Oi",
                Size = 12f,
                Style = MeasurementFontStyles.Regular
            };

            var tle = OpenTypeFonts.GetTextLayoutEngineForFont(mf, FontFolders);

            var resultStrings = tle.WrapText(TestText, mf.Size, MaxWidthInPoints);
            Assert.AreEqual(3, resultStrings.Count);
            Assert.AreEqual("Ope", resultStrings[0]);
            Assert.AreEqual("n", resultStrings[1]);
            Assert.AreEqual("sans", resultStrings[2]);
        }

